describe('Table Data Verification', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/tables');
  });

  it('should verify table structure with correct headers and row count', () => {
    // Verify table exists
    cy.get('#table1').should('exist');

    // Verify header row contains all required column headings
    cy.get('#table1 thead tr th').should('have.length', 4);
    cy.get('#table1 thead tr th').eq(0).should('contain', 'Last Name');
    cy.get('#table1 thead tr th').eq(1).should('contain', 'First Name');
    cy.get('#table1 thead tr th').eq(2).should('contain', 'Email');
    cy.get('#table1 thead tr th').eq(3).should('contain', 'Due');

    // Verify table body contains exactly 4 rows
    cy.get('#table1 tbody tr').should('have.length', 4);
  });

  it('should verify Smith row contains jsmith@gmail.com email in same row', () => {
    // Find the row containing 'Smith' in the Last Name column
    cy.get('#table1 tbody tr').each(($row) => {
      cy.wrap($row).within(() => {
        cy.get('td').eq(0).then(($cell) => {
          if ($cell.text().includes('Smith')) {
            // Verify the email column in the same row contains jsmith@gmail.com
            cy.get('td').eq(2).should('contain', 'jsmith@gmail.com');
          }
        });
      });
    });
  });

  it('should handle edge case where table data might be dynamically loaded', () => {
    // Wait for table to be visible and stable
    cy.get('#table1', { timeout: 10000 }).should('be.visible');
    cy.get('#table1 tbody tr').should('have.length', 4);

    // Verify all rows have the expected number of columns
    cy.get('#table1 tbody tr').each(($row) => {
      cy.wrap($row).find('td').should('have.length', 4);
    });

    // Verify no empty rows exist
    cy.get('#table1 tbody tr').each(($row) => {
      cy.wrap($row).find('td').each(($cell) => {
        cy.wrap($cell).should('not.be.empty');
      });
    });
  });
});
